{
       choices: this.root.choices.map((n) => ({ n: n, label: this.root.nameOf(n),
           state: !this.root.revealed ? "" : n == this.root.answer ? "right" : n == this.root.picked ? "wrong" : "" })),
       recap: this.root.seeds.map((s, t) => ({ t: t, ok: this.root.answers[t] == s, slug: this.root.slugOf(s), name: this.root.nameOf(s),
           said: this.root.nameOf(this.root.answers[t] ?? -1) })) }
